"""Create a local review report that keeps model QA distinct from field verification."""
import json,html,sys
from pathlib import Path
r=Path(sys.argv[1]);out=Path(sys.argv[2]);sp=json.loads((r/'connected_span_height_audit.json').read_text());app=json.loads((r/'connected_structure_application.json').read_text());h=json.loads((r/'streetview_height_review.json').read_text());qa=json.loads((r/'connected_structure_validation.json').read_text())
def esc(x):return html.escape(str(x))
def num(x):return '未知' if x is None else f'{x:.2f}'
rows=[]
for a in sp['spans']:
 flags=[]
 if a['ground_missing_samples']:flags.append('部分地面缺資料')
 if a['length_m']>60:flags.append('長跨／可能缺柱')
 if a['boundary_span']:flags.append('跨原橋面分段')
 rows.append(f"<tr><td>{a['span_id']}</td><td>{a['start_bent']:03d} → {a['end_bent']:03d}</td><td>{num(a['length_m'])}</td><td>{num(a['sampled_min_clearance_m'])}</td><td>{'—' if not a['deck_top_z_range'] else '–'.join(num(v) for v in a['deck_top_z_range'])}</td><td>{'、'.join(flags) or '模型取樣完整'}</td></tr>")
anchors=[]
for a in sorted(h['anchors'],key=lambda a:a['xy'][0]):
 links=[]
 for i,v in enumerate(a['views']):
  url=f"https://www.google.com/maps/@?api=1&map_action=pano&pano={v['pano']}&heading={v['heading']}&pitch={v['pitch']}&fov=90";links.append(f'<a href="{esc(url)}">視點 {i+1}</a>')
 anchors.append(f"<tr><td>{esc(a['target'])}</td><td>{a['mean_height_est_m']:.2f} m</td><td>{len(a['views'])}</td><td>{' / '.join(links)}</td></tr>")
points=app['height_profile_points'];xmin,xmax=points[0][0],points[-1][0]
poly=' '.join(f'{50+(x-xmin)/(xmax-xmin)*1100:.1f},{220-z*12:.1f}' for x,z in points)
svg=f'<svg viewBox="0 0 1200 255" role="img" aria-label="估算柱高內插剖面"><line x1="50" y1="220" x2="1150" y2="220" stroke="#536273"/><polyline points="{poly}" fill="none" stroke="#efb45d" stroke-width="3"/>'
for a in h['anchors']:
 x,z=a['xy'][0],a['mean_height_est_m'];sx=50+(x-xmin)/(xmax-xmin)*1100;sy=220-z*12;svg+=f'<circle cx="{sx:.1f}" cy="{sy:.1f}" r="5" fill="#8ed2c9"/><text x="{sx:.1f}" y="{sy-14:.1f}" fill="#e6eef3" text-anchor="middle" font-size="15">{z:.2f} m</text>'
svg+='<text x="50" y="247" fill="#9eafbd" font-size="14">西端 · 端部沿用原估算</text><text x="1150" y="247" fill="#9eafbd" text-anchor="end" font-size="14">東端 · 端部沿用原估算</text></svg>'
page='''<!doctype html><html lang="zh-Hant"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>市民大道｜柱位與支承比較版</title><style>*{box-sizing:border-box}body{margin:0;background:#111820;color:#e5edf3;font:15px/1.7 -apple-system,BlinkMacSystemFont,"Noto Sans TC",sans-serif}main{max-width:1280px;margin:auto;padding:36px 28px}h1{font-size:30px;margin:4px 0 12px}h2{margin-top:36px;font-size:21px}.sub,small{color:#a6b6c5}.note{border-left:4px solid #efb45d;padding:12px 18px;background:#252621}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:22px 0}.card{background:#1c2834;padding:18px;border-radius:10px}.card strong{display:block;font-size:28px;color:#8ed2c9}a{color:#8ed2c9}table{border-collapse:collapse;width:100%;font-size:13px}th,td{text-align:left;border-bottom:1px solid #34414f;padding:10px}th{position:sticky;top:0;background:#243240}.scroll{max-height:620px;overflow:auto;border:1px solid #34414f}input{padding:12px;width:100%;background:#1c2834;border:1px solid #536273;color:white;margin:10px 0}.gallery{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}figure{margin:0}img{width:100%;border-radius:8px}figcaption{color:#a6b6c5}.pill{display:inline-block;background:#29423e;color:#a7ded2;padding:4px 12px;border-radius:20px}@media(max-width:750px){.cards,.gallery{grid-template-columns:1fr 1fr}main{padding:20px 14px}h1{font-size:24px}}</style><main><div class="sub">2026-09-29 · Blender 比較模型</div><h1>市民大道：柱位 → 柱高 → 支承與高架銜接</h1><p class="note"><b>模型幾何修整完成；實景校準仍屬估算。</b>原 124 根道路衝突疑點都有 XY 比較位置；車道遮罩重疊已歸零。這個結果依賴估算分隔島邊界，不能當作實測無衝突證明。</p><div class="cards"><div class="card"><strong>124 / 124</strong>原疑點具 XY 比較位置</div><div class="card"><strong>258</strong>銜接柱身</div><div class="card"><strong>131</strong>柱帽比較組</div><div class="card"><strong>1,026</strong>估算支承墊</div></div><p><span class="pill">柱身 XY 保留</span> <span class="pill">支承中心接觸檢查通過</span> <span class="pill">網格封閉檢查通過</span> <span class="pill">28 組既有橋面端點無平面斷縫</span></p><h2>高度依據</h2><p>以下數值是柱腳至柱頂的街景比例估算，不是橋面標高。三組採雙視點、一組採單視點；其餘位置內插，兩端沿用原估算。相機定位、影像選點與柱前緣距離誤差尚未獨立量測。</p>'''+svg+'''<table><thead><tr><th>定位柱</th><th>估算柱高</th><th>視點數</th><th>公開來源</th></tr></thead><tbody>'''+''.join(anchors)+'''</tbody></table><h2>近景模型檢查</h2><div class="gallery"><figure><img src="connected_station_qa.png"><figcaption>車站段</figcaption></figure><figure><img src="connected_p215_qa.png"><figcaption>建國西側矩形柱</figcaption></figure><figure><img src="connected_p233_qa.png"><figcaption>復興東側 P233 附近</figcaption></figure></div><h2>仍保留的資料限制</h2><ul><li>73 根原柱位在道路底圖覆蓋外，不能宣稱已通過實景道路淨空驗證。</li><li>252 個候選跨距中，108 跨有部分地面缺資料；31 跨超過 60 m，保留缺柱／跨距配對疑點。</li><li>柱帽、支承墊尺寸與部分柱對配對為工作假設；匝道標高與分合流細節未取得獨立實測控制。</li><li>原場景完整保留，新版場景名為 CIVIC_STRUCTURE_CONNECTED_EST_20260929。</li></ul><h2>逐跨模型量測</h2><p class="sub">單位 m。每跨 11 個縱向站點 × 9 個橫向點；取樣最低值不等於連續實測最低淨高。地面缺資料保留未知。</p><input id="filter" placeholder="搜尋跨號、柱帽組號或疑點…" aria-label="篩選逐跨量測"><div class="scroll"><table id="spans"><thead><tr><th>跨號</th><th>柱帽組</th><th>平面跨距</th><th>取樣最低淨高</th><th>橋面模型 Z</th><th>檢查標記</th></tr></thead><tbody>'''+''.join(rows)+'''</tbody></table></div><p class="sub">本頁與完整量測 JSON 一同儲存於本機；公開 GitHub 只備份腳本、公開來源及精簡紀錄。</p></main><script>document.getElementById('filter').addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('#spans tbody tr').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(q))})</script></html>'''
out.write_text(page);print({'rows':len(rows),'bytes':len(page.encode())})
